INSERT INTO tb_questoes (id, enunciado, materia, dificuldade, indice_correto) VALUES
(216, 'Na oração ''Choveu torrencialmente ontem à noite'', o sujeito é classificado como:', 'PORTUGUES', 'FACIL', 1),
(217, 'Em ''Precisa-se de funcionários qualificados'', o termo ''de funcionários qualificados'' funciona como:', 'PORTUGUES', 'MEDIO', 1),
(218, 'Assinale a oração que apresenta predicado verbo-nominal:', 'PORTUGUES', 'MEDIO', 2),
(219, 'Qual figura de linguagem consiste no exagero intencional de uma ideia para causar impacto expressivo?', 'PORTUGUES', 'FACIL', 0),
(220, 'Em ''Ele descansou no sono eterno'', temos um exemplo claro de:', 'PORTUGUES', 'FACIL', 1),
(221, 'Na frase ''Ouvi um silêncio ensurdecedor na sala'', temos a figura de linguagem denominada:', 'PORTUGUES', 'MEDIO', 2),
(222, 'Em ''Li Machado de Assis com muito entusiasmo'', a troca do autor pela obra constitui uma:', 'PORTUGUES', 'FACIL', 1),
(223, 'A expressão ''dente de alho'' ou ''asa da xícara'' exemplifica qual figura de linguagem?', 'PORTUGUES', 'FACIL', 0),
(224, 'Em ''A doce melodia acalmava a alma'', a associação entre audição e paladar expressa:', 'PORTUGUES', 'MEDIO', 2),
(225, 'Qual função da linguagem é centrada no emissor e na expressão de seus sentimentos e emoções?', 'PORTUGUES', 'FACIL', 2),
(226, 'Manuais de instrução, artigos científicos e notícias jornalísticas utilizam predominantemente a função:', 'PORTUGUES', 'FACIL', 0),
(227, 'Em ''Alô? Está me ouvindo?'', a linguagem é usada para testar o canal de comunicação, caracterizando a função:', 'PORTUGUES', 'FACIL', 0),
(228, 'Anúncios publicitários que buscam persuadir o leitor (''Compre já!'') utilizam a função:', 'PORTUGUES', 'FACIL', 0),
(229, 'Um poema que reflete sobre o próprio ato de fazer poesia exemplifica a função:', 'PORTUGUES', 'MEDIO', 0),
(230, 'O uso da crase é PROIBIDO antes de:', 'PORTUGUES', 'FACIL', 0),
(231, 'Assinale a frase em que o uso do acento grave indicador de crase é FACULTATIVO:', 'PORTUGUES', 'MEDIO', 2),
(232, 'De acordo com a norma-padrão de regência, o verbo ''assistir'' no sentido de ''presenciar'' exige a preposição:', 'PORTUGUES', 'MEDIO', 2),
(233, 'O verbo ''aspirar'' no sentido de ''almejar'' rege a preposição:', 'PORTUGUES', 'MEDIO', 2),
(234, 'O verbo ''preferir'', na norma culta, deve ser construído na forma:', 'PORTUGUES', 'MEDIO', 0),
(235, 'Assinale a opção em que a concordância verbal está estritamente CORRETA:', 'PORTUGUES', 'MEDIO', 3),
(236, 'O verbo ''haver'' quando empregado no sentido de ''existir'' ou ''ocorrer'':', 'PORTUGUES', 'FACIL', 1),
(237, 'Em ''Vende-se esta bela casa de praia'', o termo ''esta bela casa de praia'' funciona sintaticamente como:', 'PORTUGUES', 'MEDIO', 2),
(238, 'Na oração ''Ela estava meio cansada no fim da tarde'', a palavra ''meio'' é:', 'PORTUGUES', 'FACIL', 2),
(239, 'Assinale a frase em que o uso dos ''porquês'' está CORRETO no final de frase interrogativa:', 'PORTUGUES', 'MEDIO', 1),
(240, 'Qual vocábulo perdeu o acento gráfico após o Novo Acordo Ortográfico?', 'PORTUGUES', 'FACIL', 2),
(241, 'Qual palavra continua acentuada graficamente após o Novo Acordo Ortográfico?', 'PORTUGUES', 'MEDIO', 0),
(242, 'Em ''Como fazia frio, acendeu a lareira'', a conjunção ''como'' introduz uma oração com valor de:', 'PORTUGUES', 'MEDIO', 1),
(243, 'Na oração ''Estudou tanto que adormeceu sobre os livros'', a conjunção ''que'' expressa ideia de:', 'PORTUGUES', 'MEDIO', 3),
(244, 'A conjunção ''conquanto'' introduz uma oração subordinada adverbial:', 'PORTUGUES', 'DIFICIL', 3),
(245, 'Em ''Quanto mais estudo, mais aprendo'', temos uma relação de:', 'PORTUGUES', 'FACIL', 2),
(246, 'O primeiro documento escrito sobre a terra brasileira em 1500 é a carta de:', 'PORTUGUES', 'FACIL', 2),
(247, 'O poeta barroco baiano conhecido como ''Boca do Inferno'' por suas sátiras ferinas foi:', 'PORTUGUES', 'FACIL', 3),
(248, 'O sermão barroco proferido pelo Padre Antônio Vieira criticando a conduta dos colonizadores é o célebre:', 'PORTUGUES', 'MEDIO', 1),
(249, 'O Arcadismo no Brasil floresceu em Vila Rica (Minas Gerais) tendo como lema latino:', 'PORTUGUES', 'MEDIO', 0),
(250, 'O poema épico ''O Uraguai'' (1769) foi composto pelo poeta árcade:', 'PORTUGUES', 'MEDIO', 0),
(251, 'O poeta árcade autor de ''Marília de Dirceu'' foi:', 'PORTUGUES', 'FACIL', 1),
(252, 'O poema indianista romântico ''I-Juca-Pirama'' (''Meu canto de morte / Guerreiros, ouvi'') é de:', 'PORTUGUES', 'FACIL', 3),
(253, 'A Segunda Geração da poesia romântica brasileira (mal-do-século, ultra-romantismo) tem como principal nome:', 'PORTUGUES', 'FACIL', 1),
(254, 'O poeta da Terceira Geração Romântica conhecido como o ''Poeta dos Escravos'' foi:', 'PORTUGUES', 'FACIL', 2),
(255, 'O romance inaugural do Realismo brasileiro publicado em 1881 por Machado de Assis é:', 'PORTUGUES', 'FACIL', 3),
(256, 'A dúvida sobre a possível traição de Capitu a Bentinho é o tema central de qual romance machadiano?', 'PORTUGUES', 'FACIL', 0),
(257, 'O romance ''O Cortiço'' (1890), marco do Naturalismo brasileiro sobre determinismo social, foi escrito por:', 'PORTUGUES', 'FACIL', 2),
(258, 'A estética literária que pregava o culto à forma, rimas raras e a ''arte pela arte'' no final do séc. XIX foi o:', 'PORTUGUES', 'FACIL', 0),
(259, 'O principal poeta parnasiano brasileiro, autor de ''Ouvir Estrelas'', foi:', 'PORTUGUES', 'FACIL', 2),
(260, 'O principal expoente do Simbolismo no Brasil, autor de ''Broquéis'', foi:', 'PORTUGUES', 'MEDIO', 1),
(261, 'A obra pré-modernista ''Os Sertões'' (1902), relatando a Guerra de Canudos, é de autoria de:', 'PORTUGUES', 'FACIL', 2),
(262, 'O romance ''Triste Fim de Policarpo Quaresma'' (1915), que satiriza o nacionalismo ingênuo, foi escrito por:', 'PORTUGUES', 'FACIL', 1),
(263, 'O evento cultural em São Paulo em fevereiro de 1922 que marcou o início do Modernismo no Brasil foi a:', 'PORTUGUES', 'FACIL', 3),
(264, 'O ''Manifesto Antropófago'' (1928) com a famosa frase ''Tupi or not tupi'' foi escrito por:', 'PORTUGUES', 'MEDIO', 0),
(265, 'O romance modernista ''Macunaíma, o herói sem nenhum caráter'' (1928) foi escrito por:', 'PORTUGUES', 'FACIL', 2);

