INSERT INTO tb_questoes (id, enunciado, materia, dificuldade, indice_correto) VALUES
(413, 'Qual organela celular é responsável pela síntese de proteínas?', 'BIOLOGIA', 'FACIL', 0),
(414, 'A digestão intracelular e a autofagia são funções primordiais de qual organela?', 'BIOLOGIA', 'FACIL', 2),
(415, 'Qual organela participa da síntese de lipídios e da desintoxicação celular (como do álcool no fígado)?', 'BIOLOGIA', 'MEDIO', 2),
(416, 'Os peroxissomos contêm a enzima catalase, responsável por degradar qual substância tóxica celular?', 'BIOLOGIA', 'MEDIO', 1),
(417, 'O modelo aceito para a estrutura da membrana plasmática é o do:', 'BIOLOGIA', 'FACIL', 2),
(418, 'O transporte de substâncias através da membrana a favor do gradiente de concentração e SEM gasto de ATP é denominado:', 'BIOLOGIA', 'FACIL', 0),
(419, 'A bomba de sódio e potássio é um exemplo clássico de:', 'BIOLOGIA', 'FACIL', 1),
(420, 'O movimento da água através de uma membrana semipermeável do meio hipotônico para o hipertônico chama-se:', 'BIOLOGIA', 'FACIL', 2),
(421, 'Em qual compartimento celular ocorre a etapa da Glicólise na respiração celular?', 'BIOLOGIA', 'MEDIO', 3),
(422, 'O Ciclo de Krebs (ciclo do ácido cítrico) ocorre em qual local da célula eucariótica?', 'BIOLOGIA', 'MEDIO', 3),
(423, 'A Fosforilação Oxidativa (cadeia respiratória) ocorre em qual estrutura da mitocôndria?', 'BIOLOGIA', 'MEDIO', 0),
(424, 'Qual é o aceptor final de elétrons e prótons na respiração celular aeróbia?', 'BIOLOGIA', 'MEDIO', 2),
(425, 'A fermentação realizada por leveduras que produz álcool etílico e gás carbônico na panificação e cervejaria é a:', 'BIOLOGIA', 'FACIL', 0),
(426, 'A produção de ácido lático nos músculos durante esforço físico extenuante em anaerobiose ocorre pela:', 'BIOLOGIA', 'FACIL', 3),
(427, 'A fase fotoquímica (fase clara) da fotossíntese ocorre em qual região do cloroplasto?', 'BIOLOGIA', 'MEDIO', 1),
(428, 'A fase química (fase escura / Ciclo de Calvin) da fotossíntese ocorre no:', 'BIOLOGIA', 'MEDIO', 3),
(429, 'A fotólise da água na fase fotoquímica da fotossíntese é responsável pela liberação de:', 'BIOLOGIA', 'FACIL', 0),
(430, 'Em qual fase da mitose ocorre o alinhamento máximo dos cromossomos duplicados na placa equatorial da célula?', 'BIOLOGIA', 'FACIL', 1),
(431, 'A separação das cromátides-irmãs para os polos opostos da célula ocorre na:', 'BIOLOGIA', 'FACIL', 3),
(432, 'O fenômeno do crossing-over (permutação gênica), que amplia a variabilidade genética, ocorre em qual fase da meiose?', 'BIOLOGIA', 'MEDIO', 3),
(433, 'A Primeira Lei de Mendel também é conhecida como o princípio da:', 'BIOLOGIA', 'FACIL', 2),
(434, 'No cruzamento entre dois indivíduos heterozigotos (Aa x Aa), qual é a proporção genotípica esperada na descendência?', 'BIOLOGIA', 'FACIL', 1),
(435, 'Qual indivíduo é considerado o ''Doador Universal'' no sistema sanguíneo ABO e Rh?', 'BIOLOGIA', 'FACIL', 3),
(436, 'Qual indivíduo é considerado o ''Receptor Universal'' no sistema ABO e Rh?', 'BIOLOGIA', 'FACIL', 2),
(437, 'A Eritroblastose Fetal (doença hemolítica do recém-nascido) pode ocorrer quando:', 'BIOLOGIA', 'MEDIO', 1),
(438, 'O daltonismo e a hemofilia clássica são exemplos de herança ligada ao cromossomo:', 'BIOLOGIA', 'MEDIO', 3),
(439, 'A teoria evolutiva que propunha a lei do uso e desuso e a herança dos caracteres adquiridos foi desenvolvida por:', 'BIOLOGIA', 'FACIL', 2),
(440, 'A teoria da evolução pela seleção natural foi proposta originalmente por:', 'BIOLOGIA', 'FACIL', 0),
(441, 'A Teoria Sintética da Evolução (Neodarwinismo) incorporou à seleção natural os conhecimentos de:', 'BIOLOGIA', 'MEDIO', 3),
(442, 'Estruturas que possuem a mesma origem embrionária, como o braço humano e a nadadeira da baleia (homologia), decorrem de:', 'BIOLOGIA', 'MEDIO', 2),
(443, 'A asa da ave e a asa do inseto realizam a mesma função, mas têm origens embrionárias distintas (analogia), resultado de:', 'BIOLOGIA', 'MEDIO', 3),
(444, 'O processo de formação de novas espécies biológicas a partir do isolamento geográfico é denominado:', 'BIOLOGIA', 'MEDIO', 0),
(445, 'Em uma cadeia alimentar, os organismos capazes de sintetizar matéria orgânica a partir de inorgânica são os:', 'BIOLOGIA', 'FACIL', 2),
(446, 'Fungos e bactérias que reciclam nutrientes na matéria orgânica morta atuam na teia alimentar como:', 'BIOLOGIA', 'FACIL', 3),
(447, 'O fluxo de energia ao longo dos níveis tróficos de uma cadeia alimentar é:', 'BIOLOGIA', 'MEDIO', 0),
(448, 'Bactérias do gênero Rhizobium associadas a raízes de leguminosas realizam qual etapa do ciclo do nitrogênio?', 'BIOLOGIA', 'MEDIO', 3),
(449, 'A relação ecológica harmônica interespecífica obrigatória com benefício mútuo (como liquens) é denominada:', 'BIOLOGIA', 'FACIL', 0),
(450, 'A relação em que uma espécie se beneficia dos restos alimentares de outra sem prejudicá-la (como rêmora e tubarão) é:', 'BIOLOGIA', 'FACIL', 3),
(451, 'A digestão das proteínas no estômago humano é iniciada por qual enzima em meio ácido com HCl?', 'BIOLOGIA', 'MEDIO', 2),
(452, 'A bile, que atua na emulsificação mecânica das gorduras no duodeno, é produzida pelo:', 'BIOLOGIA', 'FACIL', 2),
(453, 'No coração humano, qual câmara cardíaca bombeia sangue oxigenado para todo o corpo através da artéria aorta?', 'BIOLOGIA', 'MEDIO', 0),
(454, 'As trocas gasosas de oxigênio e gás carbônico que ocorrem nos alvéolos pulmonares são chamadas de:', 'BIOLOGIA', 'FACIL', 2),
(455, 'A unidade funcional filtradora dos rins humanos responsável pela formação da urina é o:', 'BIOLOGIA', 'FACIL', 1),
(456, 'O hormônio antidiurético (ADH ou vasopressina) atua nos rins promovendo:', 'BIOLOGIA', 'MEDIO', 1),
(457, 'Qual hormônio pancreático é liberado em resposta à hipoglicemia para quebrar glicogênio em glicose no fígado?', 'BIOLOGIA', 'FACIL', 3),
(458, 'Qual hormônio produzido pelas células beta das ilhotas pancreáticas reduz os níveis de glicose no sangue?', 'BIOLOGIA', 'FACIL', 0),
(459, 'A transmissão do impulso nervoso entre neurônios ocorre através de substâncias químicas em uma região chamada:', 'BIOLOGIA', 'FACIL', 0),
(460, 'A imunização ativa artificial, que introduz antígenos atenuados para estimular a produção de anticorpos e memória imunológica, é a:', 'BIOLOGIA', 'FACIL', 1),
(461, 'A imunização passiva, que injeta anticorpos prontos para ação rápida contra venenos e toxinas (como veneno de cobra), é o:', 'BIOLOGIA', 'FACIL', 0),
(462, 'Plantas avasculares de pequeno porte que dependem da água para fecundação (como musgos) são do grupo das:', 'BIOLOGIA', 'FACIL', 1);

