INSERT INTO tb_questoes (id, enunciado, materia, dificuldade, indice_correto) VALUES
(463, 'Plantas vasculares que possuem sementes nuas, sem frutos nem flores verdadeiras (como o pinheiro-do-paraná), são:', 'BIOLOGIA', 'FACIL', 1),
(464, 'As plantas que apresentam flores verdadeiras e frutos protegendo as sementes pertencem ao grupo das:', 'BIOLOGIA', 'FACIL', 0),
(465, 'Samambaias e avencas são plantas vasculares sem sementes classificadas como:', 'BIOLOGIA', 'FACIL', 3),
