INSERT INTO tb_questoes (id, enunciado, materia, dificuldade, indice_correto) VALUES
(809, 'Qual modelo atômico ficou historicamente conhecido pela analogia da ''esfera maciça, homogênea e indivisível''?', 'QUIMICA', 'FACIL', 1),
(810, 'O modelo atômico que propôs a existência de elétrons incrustados em uma massa positiva (''pudim de passas'') foi o de:', 'QUIMICA', 'FACIL', 1),
(811, 'O experimento da lâmina de ouro bombardeada por partículas alfa permitiu a Rutherford descobrir:', 'QUIMICA', 'FACIL', 2),
(812, 'O modelo atômico que introduziu órbitas circulares com níveis de energia quantizados para os elétrons foi o de:', 'QUIMICA', 'FACIL', 0),
(813, 'Átomos que possuem o mesmo número atômico (Z) e diferente número de massa (A) são chamados de:', 'QUIMICA', 'FACIL', 2),
(814, 'Átomos que possuem o mesmo número de massa (A) e diferentes números atômicos são chamados de:', 'QUIMICA', 'FACIL', 0),
(815, 'Átomos de elementos distintos que possuem o mesmo número de nêutrons são denominados:', 'QUIMICA', 'FACIL', 0),
(816, 'Na tabela periódica moderna, os elementos estão organizados em ordem crescente de seus:', 'QUIMICA', 'FACIL', 3),
(817, 'Os elementos da família 18 (VIII A) da tabela periódica, caracterizados pela alta estabilidade química de sua camada de valência, são os:', 'QUIMICA', 'FACIL', 0),
(818, 'Os elementos do Grupo 1 da tabela periódica (como sódio e potássio) são denominados:', 'QUIMICA', 'FACIL', 1),
(819, 'Os elementos químicos do Grupo 17 (como flúor, cloro, bromo e iodo) pertencem à família dos:', 'QUIMICA', 'FACIL', 1),
(820, 'A ligação química formada pela transferência definitiva de elétrons entre um metal e um ametal é a:', 'QUIMICA', 'FACIL', 0),
(821, 'A ligação química que se dá pelo compartilhamento mútuo de pares eletrônicos entre ametais é a:', 'QUIMICA', 'FACIL', 0),
(822, 'A ''teoria do mar de elétrons'' deslocalizados explica as propriedades de condução de calor e eletricidade da:', 'QUIMICA', 'FACIL', 1),
(823, 'A geometria molecular da molécula de água (H₂O), em razão dos pares eletrônicos isolados no oxigênio, é:', 'QUIMICA', 'FACIL', 1),
(824, 'A geometria molecular do gás metano (CH₄) é:', 'QUIMICA', 'FACIL', 1),
(825, 'A geometria molecular do gás carbônico (CO₂) é:', 'QUIMICA', 'FACIL', 0),
(826, 'Qual força intermolecular ocorre entre moléculas de água (H₂O) ou de amônia (NH₃), sendo excepcionalmente forte?', 'QUIMICA', 'FACIL', 1),
(827, 'Segundo a definição clássica de Arrhenius, ácido é toda substância que em solução aquosa libera como único cátion:', 'QUIMICA', 'FACIL', 0),
(828, 'Segundo a definição de Arrhenius, base (ou hidróxido) é toda substância que em água se dissocia liberando exclusivamente o ânion:', 'QUIMICA', 'FACIL', 1),
(829, 'A reação entre um ácido e uma base produzindo sal e água é denominada:', 'QUIMICA', 'FACIL', 1),
(830, 'O composto NaCl (cloreto de sódio), base do sal de cozinha comum, classifica-se quimicamente como um:', 'QUIMICA', 'FACIL', 3),
(831, 'O gás carbônico (CO₂) e o trióxido de enxofre (SO₃), que reagem com água formando ácidos na chuva ácida, são:', 'QUIMICA', 'MEDIO', 0),
(832, 'O monóxido de carbono (CO) e o monóxido de nitrogênio (NO) são classificados como óxidos que não reagem com água nem ácidos/bases, denominados:', 'QUIMICA', 'MEDIO', 3),
(833, 'A Lei da Conservação das Massas (''Na natureza nada se cria, nada se perde, tudo se transforma'') foi enunciada por:', 'QUIMICA', 'FACIL', 0),
(834, 'A Lei das Proporções Definidas ou Constantes é de autoria do químico francês:', 'QUIMICA', 'MEDIO', 1),
(835, 'O valor da Constante de Avogadro correspondente ao número de entidades elementares em 1 mol é de aproximadamente:', 'QUIMICA', 'FACIL', 1),
(836, 'O volume molar ocupado por 1 mol de qualquer gás ideal nas Condições Normais de Temperatura e Pressão (CNTP: 0°C e 1 atm) é de:', 'QUIMICA', 'FACIL', 0),
(837, 'Qual é a massa molar da água (H₂O), dados: H = 1 g/mol e O = 16 g/mol?', 'QUIMICA', 'FACIL', 0),
(838, 'Qual é a massa molar do gás carbônico (CO₂), dados: C = 12 g/mol e O = 16 g/mol?', 'QUIMICA', 'FACIL', 3),
(839, 'Uma solução aquosa que contém a quantidade máxima possível de soluto dissolvido a uma dada temperatura é chamada de:', 'QUIMICA', 'FACIL', 3),
(840, 'A concentração comum de uma solução obtida dissolvendo-se 20 g de sal em água até o volume de 2 litros é:', 'QUIMICA', 'FACIL', 1),
(841, 'Uma reação química que LIBERA calor para o meio ambiente e possui variação de entalpia negativa (ΔH < 0) é dita:', 'QUIMICA', 'FACIL', 0),
(842, 'Uma reação química que ABSORVE calor do meio e apresenta variação de entalpia positiva (ΔH > 0) é denominada:', 'QUIMICA', 'FACIL', 3),
(843, 'A Lei da Termoquímica que afirma que a variação de entalpia de uma reação independe do caminho e depende apenas dos estados inicial e final é a:', 'QUIMICA', 'MEDIO', 2),
(844, 'O estado de uma reação química reversível no qual as velocidades das reações direta e inversa se igualam é o:', 'QUIMICA', 'FACIL', 0),
(845, 'O princípio que prevê que um sistema em equilíbrio, quando perturbado, desloca-se no sentido de atenuar a perturbação é o:', 'QUIMICA', 'MEDIO', 1),
(846, 'Uma substância que acelera a velocidade de uma reação química diminuindo sua energia de ativação sem ser consumida é um:', 'QUIMICA', 'FACIL', 2),
(847, 'Em uma escala de pH a 25 °C, uma solução ácida possui pH:', 'QUIMICA', 'FACIL', 3),
(848, 'Em uma solução a 25 °C com concentração de íons [H⁺] = 10⁻³ mol/L, o valor do pH é igual a:', 'QUIMICA', 'FACIL', 3),
(849, 'Em uma reação de oxirredução, a espécie química que PERDE elétrons sofre:', 'QUIMICA', 'FACIL', 0),
(850, 'Em uma reação de oxirredução, a espécie química que GANHA elétrons sofre:', 'QUIMICA', 'FACIL', 2),
(851, 'Em uma pilha eletroquímica galvânica (como a pilha de Daniell), o eletrodo no qual ocorre a oxidação é o:', 'QUIMICA', 'MEDIO', 1),
(852, 'Na pilha de Daniell, o eletrodo no qual ocorre a redução dos íons de cobre é o:', 'QUIMICA', 'MEDIO', 0),
(853, 'O postulado fundamental da Química Orgânica proposto por Friedrich August Kekulé estabelece que o átomo de carbono é:', 'QUIMICA', 'FACIL', 2),
(854, 'Hidrocarbonetos alifáticos saturados de cadeia aberta que possuem apenas ligações simples entre carbonos são os:', 'QUIMICA', 'FACIL', 3),
(855, 'Hidrocarbonetos de cadeia aberta que possuem uma ligação dupla entre átomos de carbono são chamados de:', 'QUIMICA', 'FACIL', 3),
(856, 'Hidrocarbonetos alifáticos de cadeia aberta que apresentam uma ligação tripla entre carbonos são os:', 'QUIMICA', 'FACIL', 1),
(857, 'Qual é a fórmula molecular do gás metano, hidrocarboneto mais simples e principal componente do gás natural?', 'QUIMICA', 'FACIL', 1),
(858, 'O hidrocarboneto aromático de fórmula molecular C₆H₆ com anel benzênico ressonante é o:', 'QUIMICA', 'FACIL', 0);

