INSERT INTO tb_questoes (id, enunciado, materia, dificuldade, indice_correto) VALUES
(1007, 'O mais antigo código de leis escritas conhecido da Mesopotâmia antiga baseado na Lei de Talião (''olho por olho, dente por dente'') é o:', 'HISTORIA', 'FACIL', 3),
(1008, 'A civilização egípcia desenvolveu-se ao longo do vale fértil proporcionado pelas cheias periódicas do rio:', 'HISTORIA', 'FACIL', 0),
(1009, 'Qual povo da Antiguidade Oriental destacou-se pelo comércio marítimo no Mediterrâneo e pela invenção do alfabeto fonético?', 'HISTORIA', 'FACIL', 0),
(1010, 'O sistema político pioneiro desenvolvido em Atenas durante o período clássico no qual cidadãos livres votavam diretamente na Eclésia foi a:', 'HISTORIA', 'FACIL', 1),
(1011, 'A pólis grega caracterizada por sua estrutura social rigidamente militarizada e oligárquica governada por esparciatas foi:', 'HISTORIA', 'FACIL', 3),
(1012, 'A Guerra do Peloponeso (431-404 a.C.) foi o grande conflito militar travado no mundo grego entre:', 'HISTORIA', 'MEDIO', 3),
(1013, 'As Guerras Púnicas na Antiguidade Clássica foram travadas entre Roma e qual potência marítima do norte da África pelo controle do Mediterrâneo?', 'HISTORIA', 'FACIL', 0),
(1014, 'A primeira lei escrita da Roma Antiga, conquistada pela pressão das revoltas da plebe romana em 450 a.C., foi a:', 'HISTORIA', 'FACIL', 2),
(1015, 'O primeiro imperador romano, cujo governo inaugurou o período de apogeu conhecido como Pax Romana, foi:', 'HISTORIA', 'FACIL', 1),
(1016, 'O documento promulgado pelo imperador Constantino em 313 d.C. que concedeu liberdade de culto aos cristãos no Império Romano foi o:', 'HISTORIA', 'MEDIO', 1),
(1017, 'O Édito de Tessalônica (380 d.C.), emitido pelo imperador Teodósio, teve como marco histórico:', 'HISTORIA', 'MEDIO', 0),
(1018, 'O marco que assinala a queda do Império Romano do Ocidente e o início da Idade Média em 476 d.C. foi a invasão de Roma pelos:', 'HISTORIA', 'FACIL', 2),
(1019, 'A sociedade feudal medieval caracterizava-se por ser estamental e dividida rigidamente entre os que rezam, os que lutam e os que trabalham, isto é:', 'HISTORIA', 'FACIL', 0),
(1020, 'O juramento de fidelidade e apoio militar mútuo entre nobres na Idade Média constituía a relação de:', 'HISTORIA', 'FACIL', 1),
(1021, 'O tributo feudal pago pelos servos que consistia em trabalhar compulsoriamente alguns dias da semana nas terras diretas do senhor (manso senhorial) era a:', 'HISTORIA', 'FACIL', 1),
(1022, 'A epidemia de peste bubônica que dizimou cerca de um terço da população europeia no século XIV ficou conhecida como:', 'HISTORIA', 'FACIL', 0),
(1023, 'As expedições militares organizadas pela Igreja Católica entre os séculos XI e XIII para retomar a Terra Santa (Jerusalém) dos muçulmanos foram as:', 'HISTORIA', 'FACIL', 1),
(1024, 'O movimento cultural e artístico surgido na Península Itálica no século XIV que resgatou os valores da Antiguidade Clássica foi o:', 'HISTORIA', 'FACIL', 3),
(1025, 'A visão renascentista que colocou o ser humano e a razão no centro das preocupações intelectuais em oposição ao teocentrismo medieval foi o:', 'HISTORIA', 'FACIL', 2),
(1026, 'A prática mercantilista de acumular metais preciosos (ouro e prata) dentro do Estado Nacional é o:', 'HISTORIA', 'FACIL', 3),
(1027, 'O Tratado de Tordesilhas assinado em 1494 dividiu as terras recém-descobertas fora da Europa entre quais potências?', 'HISTORIA', 'FACIL', 1),
(1028, 'O monge alemão que afixou as 95 Teses na porta da igreja de Wittenberg em 1517, iniciando a Reforma Protestante, foi:', 'HISTORIA', 'FACIL', 2),
(1029, 'A doutrina calvinista diferenciava-se do luteranismo principalmente por defender de forma enfática a:', 'HISTORIA', 'MEDIO', 1),
