-- ------------------------------------------------------------------------------
-- GEOGRAFIA: 198 novas questões (IDs 1205 a 1402)
-- ------------------------------------------------------------------------------
INSERT INTO tb_questoes (id, enunciado, materia, dificuldade, indice_correto) VALUES
(1205, 'A camada mais interna da Terra, composta predominantemente por níquel e ferro em altíssimas temperaturas, é o:', 'GEOGRAFIA', 'FACIL', 2),
(1206, 'A teoria formulada por Alfred Wegener em 1912 propondo que os continentes formavam uma única massa territorial (Pangeia) é a:', 'GEOGRAFIA', 'FACIL', 2),
(1207, 'O ponto no interior da crosta terrestre onde tem origem o terremoto (liberação da energia sísmica) é chamado de:', 'GEOGRAFIA', 'FACIL', 3),
(1208, 'O ponto na superfície terrestre localizado verticalmente acima da origem de um sismo é o:', 'GEOGRAFIA', 'FACIL', 3),
(1209, 'Rochas formadas pelo resfriamento e solidificação do magma (como granito e basalto) são chamadas de:', 'GEOGRAFIA', 'FACIL', 2),
(1210, 'Rochas originadas pela desagregação, transporte e compactação de sedimentos (como arenito e calcário) são as:', 'GEOGRAFIA', 'FACIL', 3),
(1211, 'Rochas resultantes da alteração físico-química de rochas pré-existentes sob alta pressão e temperatura (como mármore e gnaisse) são as:', 'GEOGRAFIA', 'FACIL', 0),
(1212, 'O relevo brasileiro caracteriza-se geologicamente por sua antiguidade e pela ausência de:', 'GEOGRAFIA', 'FACIL', 2),
(1213, 'A camada da atmosfera onde ocorrem praticamente todos os fenômenos climáticos e meteorológicos (nuvens, chuvas, ventos) é a:', 'GEOGRAFIA', 'FACIL', 2),
(1214, 'A camada de ozônio (O₃), responsável por filtrar a radiação ultravioleta prejudicial do Sol, localiza-se na:', 'GEOGRAFIA', 'FACIL', 0),
(1215, 'O fator climático que explica por que cidades de maior altitude (como Campos do Jordão) são mais frias do que cidades no nível do mar é a:', 'GEOGRAFIA', 'FACIL', 1),
(1216, 'O fenômeno pelo qual cidades litorâneas apresentam menor variação entre a temperatura máxima e mínima (menor amplitude térmica) decorre da:', 'GEOGRAFIA', 'FACIL', 3),
(1217, 'As chuvas causadas pela subida forçada de massas de ar úmido ao encontrarem barreiras montanhosas (como a Serra do Mar) são as chuvas:', 'GEOGRAFIA', 'MEDIO', 1),
(1218, 'O clima predominante na Região Norte do Brasil com chuvas abundantes o ano todo e baixa amplitude térmica é o:', 'GEOGRAFIA', 'FACIL', 0),
(1219, 'O tipo climático caracterizado por apresentar duas estações bem definidas (verão chuvoso e inverno seco), típico do Brasil Central, é o:', 'GEOGRAFIA', 'FACIL', 1),
(1220, 'O clima do Sertão nordestino caracterizado pela escassez e irregularidade das precipitações pluviais é o:', 'GEOGRAFIA', 'FACIL', 1),
(1221, 'O clima da Região Sul do Brasil que apresenta temperaturas amenas, geadas no inverno e precipitações bem distribuídas ao longo de todo o ano é o:', 'GEOGRAFIA', 'FACIL', 3),
(1222, 'O fenômeno meteorológico de aquecimento anormal das águas superficiais do Oceano Pacífico equatorial que altera as chuvas globais é o:', 'GEOGRAFIA', 'FACIL', 0),
(1223, 'O resfriamento anormal das águas superficiais do Pacífico equatorial é o fenômeno denominado:', 'GEOGRAFIA', 'FACIL', 1),
(1224, 'O fenômeno climático comum em centros urbanos no inverno no qual o ar frio denso fica retido junto ao solo impedindo a dispersão de poluentes é a:', 'GEOGRAFIA', 'MEDIO', 3),
(1225, 'A elevação acentuada da temperatura nas áreas centrais das grandes metrópoles devido à grande concentração de asfalto, concreto e escassez de vegetação é a:', 'GEOGRAFIA', 'FACIL', 2),
(1226, 'O maior bioma brasileiro em extensão territorial e detentor da maior bacia hidrográfica do planeta é a:', 'GEOGRAFIA', 'FACIL', 0),
(1227, 'O bioma da savana brasileira caracterizado por árvores de casca grossa, troncos retorcidos, raízes profundas e solos ácidos é o:', 'GEOGRAFIA', 'FACIL', 0),
(1228, 'O bioma exclusivamente brasileiro caracterizado pela vegetação xerófila adaptada ao semiárido (como cactos e mandacaru) é a:', 'GEOGRAFIA', 'FACIL', 1),
(1229, 'O bioma florestal brasileiro que cobria grande parte da costa leste e que hoje possui menos de 12% de sua área original preservada é a:', 'GEOGRAFIA', 'FACIL', 0),
(1230, 'A maior planície de inundação periódica do mundo localizada entre os estados de Mato Grosso e Mato Grosso do Sul é o:', 'GEOGRAFIA', 'FACIL', 3),
(1231, 'A Bacia Hidrográfica de maior aproveitamento hidrelétrico instalado no Brasil, onde se localiza a Usina Binacional de Itaipu, é a:', 'GEOGRAFIA', 'FACIL', 3),
(1232, 'O rio historicamente conhecido como o ''Rio dos Currais'' e ''Rio da Integração Nacional'' que atravessa Minas Gerais e o Nordeste é o:', 'GEOGRAFIA', 'FACIL', 2),
(1233, 'A maior bacia hidrográfica que se localiza inteiramente em território brasileiro é a:', 'GEOGRAFIA', 'MEDIO', 1),
(1234, 'O imenso reservatório de água subterrânea que se estende sob territórios de Brasil, Argentina, Paraguai e Uruguai é o:', 'GEOGRAFIA', 'FACIL', 1),
(1235, 'A relação entre o número total de habitantes e a área territorial em km² de um país ou região define a:', 'GEOGRAFIA', 'FACIL', 0),
(1236, 'Um país que possui um número muito grande de habitantes (como a China e a Índia) é classificado geograficamente como:', 'GEOGRAFIA', 'FACIL', 1),
(1237, 'Um país que apresenta alta densidade demográfica (muitos habitantes por km², como Japão e Holanda) é classificado como:', 'GEOGRAFIA', 'FACIL', 3),
(1238, 'A diferença aritmética entre a taxa de natalidade e a taxa de mortalidade de uma população determina o:', 'GEOGRAFIA', 'FACIL', 1),
(1239, 'O número médio de filhos que uma mulher teria durante o seu período fértil em uma dada população é a:', 'GEOGRAFIA', 'FACIL', 3),
(1240, 'A pirâmide etária de um país que passa pela transição demográfica avançada com envelhecimento populacional apresenta:', 'GEOGRAFIA', 'MEDIO', 0),
(1241, 'O deslocamento diário de ida e volta realizado por trabalhadores entre cidades vizinhas dormitório e a metrópole central é a migração:', 'GEOGRAFIA', 'FACIL', 3),
(1242, 'A saída em massa da população do campo em direção às cidades industriais em busca de trabalho e serviços é denominada:', 'GEOGRAFIA', 'FACIL', 1),
(1243, 'A união física contínua da mancha urbana de dois ou mais municípios vizinhos devido ao crescimento horizontal das cidades é a:', 'GEOGRAFIA', 'FACIL', 3),
(1244, 'Uma cidade que polariza e exerce influência econômica, cultural e política sobre toda uma rede urbana regional ou nacional é uma:', 'GEOGRAFIA', 'FACIL', 2),
(1245, 'Cidades que concentram sedes financeiras, grandes bolsas de valores e comandam os fluxos econômicos da globalização (como SP, NY e Londres) são:', 'GEOGRAFIA', 'FACIL', 1),
(1246, 'O processo imobiliário de transformação e valorização de bairros degradados que eleva o custo de vida e expulsa moradores de baixa renda é a:', 'GEOGRAFIA', 'MEDIO', 1),
(1247, 'A estrutura fundiária no Brasil é historicamente caracterizada por:', 'GEOGRAFIA', 'FACIL', 3),
(1248, 'O setor econômico agrícola familiar no Brasil destaca-se por ser responsável pela maior parte da:', 'GEOGRAFIA', 'FACIL', 3),
(1249, 'A Lei de Terras de 1850 no Brasil teve como impacto histórico:', 'GEOGRAFIA', 'MEDIO', 3),
(1250, 'O modelo de produção fabril do século XX caracterizado pela linha de montagem esteira rolante e produção em massa homogênea é o:', 'GEOGRAFIA', 'FACIL', 0),
(1251, 'O modelo industrial flexível pós-1970 baseado na produção sob demanda (''just-in-time'') e controle total de qualidade é o:', 'GEOGRAFIA', 'FACIL', 1),
(1252, 'A fonte de energia que mais contribui na matriz elétrica brasileira para a geração de eletricidade é a:', 'GEOGRAFIA', 'FACIL', 0),
(1253, 'O bloco econômico sul-americano criado pelo Tratado de Assunção em 1991, formado por Brasil, Argentina, Paraguai e Uruguai, é o:', 'GEOGRAFIA', 'FACIL', 0),
(1254, 'A União Europeia situa-se no estágio mais avançado de integração regional de blocos econômicos, classificado como:', 'GEOGRAFIA', 'MEDIO', 2);

