INSERT INTO tb_questoes (id, enunciado, materia, dificuldade, indice_correto) VALUES
(1403, 'A passagem do pensamento mítico para o pensamento filosófico na Grécia Antiga significou a transição do:', 'FILOSOFIA', 'FACIL', 3),
(1404, 'A busca pelo princípio cosmológico primordial formador de todas as coisas (arché) caracterizou os filósofos:', 'FILOSOFIA', 'FACIL', 1),
(1405, 'Tales de Mileto, considerado o primeiro filósofo ocidental, postulava que a origem de todas as coisas era a:', 'FILOSOFIA', 'FACIL', 2),
(1406, 'O filósofo pré-socrático de Éfeso que afirmava que ''tudo flui e nada permanece'' e que ''ninguém entra no mesmo rio duas vezes'' foi:', 'FILOSOFIA', 'FACIL', 2),
(1407, 'O filósofo de Eleia que se opunha à ideia de mudança de Heráclito, afirmando que ''o ser é e o não-ser não é'' (o ser é uno e imóvel), foi:', 'FILOSOFIA', 'MEDIO', 3),
(1408, 'O método investigativo de Sócrates baseado em perguntas sucessivas para levar o interlocutor a dar à luz novas ideias na alma é a:', 'FILOSOFIA', 'FACIL', 3),
(1409, 'A famosa máxima socrática que expressa a consciência da própria ignorância como ponto de partida da sabedoria é:', 'FILOSOFIA', 'FACIL', 1),
(1410, 'Os pensadores gregos da época de Sócrates que cobravam para ensinar a arte da retórica e defendiam o relativismo da verdade eram os:', 'FILOSOFIA', 'FACIL', 1),
(1411, 'A célebre frase ''O homem é a medida de todas as coisas'' que resume o relativismo gnosiológico é de autoria do sofista:', 'FILOSOFIA', 'FACIL', 0),
(1412, 'A Teoria das Ideias de Platão estabelece a separação ontológica entre dois mundos fundamentais:', 'FILOSOFIA', 'FACIL', 0),
(1413, 'A narrativa platônica que ilustra a saída das ilusões dos sentidos em direção ao conhecimento racional da Verdade é a:', 'FILOSOFIA', 'FACIL', 1),
(1414, 'Na cidade ideal descrita por Platão em ''A República'' (Calípolis), o governo supremo deve ser exercido pelos:', 'FILOSOFIA', 'FACIL', 0),
(1415, 'Aristóteles criticou a teoria das ideias de Platão e formulou a teoria hilemórfica, afirmando que todos os seres materiais são compostos por:', 'FILOSOFIA', 'MEDIO', 2),
(1416, 'A distinção aristotélica que explica a capacidade de mudança das coisas (ex: a semente pode se tornar árvore) é o binômio:', 'FILOSOFIA', 'MEDIO', 0),
(1417, 'Na teoria das quatro causas de Aristóteles, a causa que se refere à finalidade ou propósito para o qual a coisa existe é a:', 'FILOSOFIA', 'FACIL', 1),
(1418, 'Na Ética a Nicômaco, Aristóteles defende que a virtude moral (aretê) consiste no:', 'FILOSOFIA', 'FACIL', 1),
(1419, 'Para Aristóteles, o ser humano é por natureza um:', 'FILOSOFIA', 'FACIL', 3),
(1420, 'A corrente helenística fundada por Epicuro que buscava a ataraxia (imperturbabilidade da alma) por meio de prazeres moderados é o:', 'FILOSOFIA', 'FACIL', 1),
(1421, 'A corrente helenística representada por Sêneca e Marco Aurélio que defendia o controle racional das paixões e aceitação do destino foi o:', 'FILOSOFIA', 'FACIL', 0),
(1422, 'O filósofo grego cínico que vivia em um barril pelas ruas de Atenas desdenhando dos bens materiais e das convenções foi:', 'FILOSOFIA', 'FACIL', 2),
(1423, 'A atitude filosófica do ceticismo pirrônico que consiste na suspensão do juízo diante de teses contraditórias de igual força é a:', 'FILOSOFIA', 'MEDIO', 0),
(1424, 'O principal filósofo da Patrística medieval que sintetizou o cristianismo com a filosofia neoplatônica foi:', 'FILOSOFIA', 'FACIL', 1),
(1425, 'Para Santo Agostinho, a origem do mal moral no mundo decorre do:', 'FILOSOFIA', 'MEDIO', 2),
(1426, 'A teoria agostiniana que afirma que o ser humano só pode alcançar as verdades eternas e imutáveis com auxílio da graça de Deus é a:', 'FILOSOFIA', 'MEDIO', 2),
(1427, 'O ápice da Escolástica medieval com a harmonização entre a fé cristã e a razão aristotélica foi alcançado por:', 'FILOSOFIA', 'FACIL', 0),
(1428, 'As provas lógicas formuladas por São Tomás de Aquino para demonstrar racionalmente a existência de Deus ficaram conhecidas como:', 'FILOSOFIA', 'FACIL', 2),
(1429, 'O pensador renascentista florentino autor de ''O Príncipe'' que fundou a Ciência Política moderna ao separar a política da moral tradicional foi:', 'FILOSOFIA', 'FACIL', 3),
(1430, 'Na obra ''O Príncipe'' de Maquiavel, os conceitos que designam a capacidade estratégica/habilidade do governante e a sorte/circunstâncias são:', 'FILOSOFIA', 'FACIL', 3),
(1431, 'O pensador francês considerado o ''Pai da Filosofia Moderna'' que utilizou a dúvida metódica e formulou o ''Cogito ergo sum'' foi:', 'FILOSOFIA', 'FACIL', 0),
(1432, 'A certeza indubitável que Descartes alcança após a experiência da dúvida metódica/hiperbólica é:', 'FILOSOFIA', 'FACIL', 3),
(1433, 'O filósofo empirista inglês autor do ''Novum Organum'' célebre pelo aforismo ''saber é poder'' que criou a Teoria dos Ídolos foi:', 'FILOSOFIA', 'FACIL', 0),
(1434, 'O filósofo empirista inglês que defendia que a mente humana nasce como uma ''tábula rasa'' (papel em branco) sem ideias inatas foi:', 'FILOSOFIA', 'FACIL', 0),
(1435, 'O filósofo empirista e cético escocês que questionou o princípio de causalidade necessária, afirmando que ela se baseia no hábito, foi:', 'FILOSOFIA', 'MEDIO', 2),
(1436, 'O teórico contratualista que descreveu o estado de natureza como uma ''guerra de todos contra todos'' (''o homem é o lobo do homem'') foi:', 'FILOSOFIA', 'FACIL', 2),
(1437, 'Para Thomas Hobbes, a única forma de superar a violência e o medo no estado de natureza é a celebração de um pacto que institua:', 'FILOSOFIA', 'FACIL', 0),
(1438, 'John Locke, considerado o pai do liberalismo político, defendia que no estado de natureza os indivíduos já possuem direitos naturais a:', 'FILOSOFIA', 'FACIL', 0),
(1439, 'O filósofo genebrino que afirmava que ''o homem nasce bom, mas a sociedade o corrompe'' ao criar a propriedade privada foi:', 'FILOSOFIA', 'FACIL', 1),
(1440, 'Em ''Do Contrato Social'', Rousseau defende que a soberania política legítima pertence ao povo e deve se guiar pela:', 'FILOSOFIA', 'MEDIO', 1),
(1441, 'O filósofo iluminista alemão autor da ''Crítica da Razão Pura'' que sintetizou o racionalismo e o empirismo (Criticismo) foi:', 'FILOSOFIA', 'FACIL', 3),
(1442, 'O princípio ético deontológico kantiano formulado como ''Age apenas segundo uma máxima tal que possas querer que se torne lei universal'' é o:', 'FILOSOFIA', 'FACIL', 1),
(1443, 'Em seu ensaio ''Resposta à pergunta: O que é o Esclarecimento?'', Kant define a Aufklärung como:', 'FILOSOFIA', 'MEDIO', 1),
(1444, 'A concepção filosófica de Georg Wilhelm Friedrich Hegel fundamenta-se na compreensão da realidade como um devir histórico regido pela:', 'FILOSOFIA', 'MEDIO', 3),
(1445, 'O filósofo alemão autor de ''O Mundo como Vontade e Representação'' que afirmava que ''a vida oscila, como um pêndulo, da dor ao tédio'' foi:', 'FILOSOFIA', 'MEDIO', 2),
(1446, 'O filósofo alemão autor de ''Assim Falou Zaratustra'' que proclamou a ''Morte de Deus'' e criticou a moral de escravos foi:', 'FILOSOFIA', 'FACIL', 2),
(1447, 'O conceito nietzschiano que representa o indivíduo soberano capaz de criar seus próprios valores e superar o niilismo é o:', 'FILOSOFIA', 'FACIL', 3),
(1448, 'A tese central do Existencialismo sartreano apresentada em ''O Existencialismo é um Humanismo'' afirma que:', 'FILOSOFIA', 'FACIL', 0),
(1449, 'Para Jean-Paul Sartre, por não possuir nenhuma natureza prévia pré-determinada, o ser humano está:', 'FILOSOFIA', 'FACIL', 3),
(1450, 'A filósofa existencialista francesa autora de ''O Segundo Sexo'' célebre pela frase ''Não se nasce mulher, torna-se mulher'' foi:', 'FILOSOFIA', 'FACIL', 2),
(1451, 'A filósofa alemã que cunhou o célebre conceito da ''Banalidade do Mal'' ao cobrir o julgamento do nazista Adolf Eichmann em Jerusalém foi:', 'FILOSOFIA', 'MEDIO', 2),
(1452, 'Os filósofos Theodor Adorno e Max Horkheimer da Escola de Frankfurt formularam o conceito crítico de:', 'FILOSOFIA', 'MEDIO', 1);

