INSERT INTO tb_questoes (id, enunciado, materia, dificuldade, indice_correto) VALUES
(1602, 'O contexto histórico e socioeconômico da Europa ocidental que propiciou o surgimento da Sociologia no século XIX foi a:', 'SOCIOLOGIA', 'FACIL', 1),
(1603, 'O pensador francês considerado o ''Pai do Positivismo'' que originalmente chamou a Sociologia de ''Física Social'' foi:', 'SOCIOLOGIA', 'FACIL', 3),
(1604, 'A Lei dos Três Estados formulada por Auguste Comte afirma que o conhecimento humano evolui sucessivamente pelas fases:', 'SOCIOLOGIA', 'MEDIO', 1),
(1605, 'O sociólogo francês responsável por institucionalizar a Sociologia como disciplina acadêmica de método próprio foi:', 'SOCIOLOGIA', 'FACIL', 2),
(1606, 'O objeto central de estudo da Sociologia estabelecido por Émile Durkheim é o:', 'SOCIOLOGIA', 'FACIL', 0),
(1607, 'As três características definidoras de um Fato Social segundo Émile Durkheim são:', 'SOCIOLOGIA', 'FACIL', 2),
(1608, 'A regra metodológica fundamental enunciada por Durkheim em ''As Regras do Método Sociológico'' exige tratar os fatos sociais:', 'SOCIOLOGIA', 'FACIL', 0),
(1609, 'Para Durkheim, a solidariedade típica de sociedades pré-capitalistas tradicionais com baixa divisão do trabalho social é a:', 'SOCIOLOGIA', 'FACIL', 1),
(1610, 'A solidariedade característica das sociedades modernas industriais, fundada na alta especialização do trabalho e interdependência, é a:', 'SOCIOLOGIA', 'FACIL', 3),
(1611, 'O conceito sociológico durkheimiano que designa o estado de ausência, enfraquecimento ou descompasso das regras e normas morais em uma sociedade é a:', 'SOCIOLOGIA', 'MEDIO', 0),
(1612, 'Em sua obra clássica ''O Suicídio'', Durkheim demonstra que o ato de tirar a própria vida possui determinantes eminentemente:', 'SOCIOLOGIA', 'MEDIO', 1),
(1613, 'O sociólogo alemão que fundou a Sociologia Compreensiva focada na interpretação do sentido atribuído pelo indivíduo à sua conduta foi:', 'SOCIOLOGIA', 'FACIL', 1),
(1614, 'O objeto central de investigação da sociologia compreensiva de Max Weber é a:', 'SOCIOLOGIA', 'FACIL', 3),
(1615, 'Para Max Weber, a conduta humana torna-se uma Ação Social quando:', 'SOCIOLOGIA', 'FACIL', 1),
(1616, 'O instrumento metodológico abstrato criado por Max Weber que acentua traços da realidade para fins de comparação e análise teórica é o:', 'SOCIOLOGIA', 'MEDIO', 2),
(1617, 'Qual dos seguintes NÃO é um dos quatro tipos puros de Ação Social propostos por Max Weber?', 'SOCIOLOGIA', 'MEDIO', 0),
(1618, 'Em ''A Ética Protestante e o Espírito do Capitalismo'', Weber estabelece uma afinidade eletiva entre a ascese intramundana do Calvinismo e o:', 'SOCIOLOGIA', 'MEDIO', 0),
(1619, 'A teoria da dominação legítima de Max Weber identifica três tipos puros de autoridade aceita pela sociedade:', 'SOCIOLOGIA', 'FACIL', 3),
(1620, 'O tipo de dominação weberiana fundamentada na crença na legalidade de estatutos, regras impessoais e na burocracia estatal é a:', 'SOCIOLOGIA', 'FACIL', 3),
(1621, 'O conceito formulado por Max Weber para descrever a perda do caráter sagrado e mágico da explicação do mundo com o avanço da ciência é o:', 'SOCIOLOGIA', 'MEDIO', 3),
(1622, 'O filósofo e sociólogo alemão que elaborou com Friedrich Engels a teoria do Materialismo Histórico e Dialético foi:', 'SOCIOLOGIA', 'FACIL', 2),
(1623, 'Para Karl Marx, o motor que impulsiona o desenvolvimento de toda a história humana até os dias atuais é a:', 'SOCIOLOGIA', 'FACIL', 3),
(1624, 'Na teoria marxista, as duas classes sociais antagônicas fundamentais do modo de produção capitalista são:', 'SOCIOLOGIA', 'FACIL', 0),
(1625, 'Para Karl Marx, a base material econômica da sociedade composta pelas forças produtivas e relações sociais de produção é a:', 'SOCIOLOGIA', 'MEDIO', 3),
(1626, 'Na teoria marxista, a Superestrutura da sociedade é composta por:', 'SOCIOLOGIA', 'MEDIO', 3),
(1627, 'O conceito marxista que designa o excedente de trabalho não pago ao operário que constitui a fonte do lucro capitalista é a:', 'SOCIOLOGIA', 'FACIL', 2),
(1628, 'A mais-valia obtida mediante o aumento direto da jornada diária de trabalho sem o respectivo aumento salarial é a:', 'SOCIOLOGIA', 'MEDIO', 3),
(1629, 'A mais-valia obtida pelo aumento da produtividade do trabalho decorrente da introdução de tecnologia e mecanização fabril é a:', 'SOCIOLOGIA', 'MEDIO', 1),
(1630, 'O processo pelo qual o trabalhador perde o controle sobre sua própria atividade e não se reconhece no produto que fabrica é a:', 'SOCIOLOGIA', 'FACIL', 1),
(1631, 'Para Marx, a Ideologia atua na sociedade capitalista como:', 'SOCIOLOGIA', 'MEDIO', 3),
(1632, 'O processo de socialização que ocorre na infância no âmbito familiar e transmite os elementos básicos da cultura e linguagem é a:', 'SOCIOLOGIA', 'FACIL', 1),
(1633, 'O processo contínuo de socialização que ocorre ao longo da vida adulta na escola, no trabalho, em igrejas e na mídia é a:', 'SOCIOLOGIA', 'FACIL', 3),
(1634, 'A atitude preconceituosa de julgar a cultura de outro povo a partir dos padrões da própria cultura, considerando o outro inferior, é o:', 'SOCIOLOGIA', 'FACIL', 2),
(1635, 'A perspectiva antropológica que compreende que cada manifestação cultural deve ser analisada dentro de seus próprios termos e contextos é o:', 'SOCIOLOGIA', 'FACIL', 1),
(1636, 'O sociólogo francês autor de ''A Reprodução'' e ''A Distinção'' que formulou os conceitos de habitus e violência simbólica foi:', 'SOCIOLOGIA', 'MEDIO', 1),
(1637, 'Na teoria de Pierre Bourdieu, o sistema de disposições incorporadas pelos indivíduos que orienta gostos, ações e escolhas é o:', 'SOCIOLOGIA', 'MEDIO', 0),
(1638, 'Para Bourdieu, diplomas acadêmicos, títulos escolares e erudição cultural constituem qual tipo de capital?', 'SOCIOLOGIA', 'MEDIO', 2),
(1639, 'A forma de violência sutil e invisível que é exercida com a cumplicidade involuntária do próprio dominado que a aceita como legítima é a:', 'SOCIOLOGIA', 'MEDIO', 0),
(1640, 'A forma histórica de estratificação social rígida, hereditária e fechada, baseada em critérios religiosos sem mobilidade social (como na Índia antiga), é o sistema de:', 'SOCIOLOGIA', 'FACIL', 1),
(1641, 'A forma de estratificação social aberta típica da modernidade capitalista baseada fundamentalmente em critérios econômicos de renda e posse é o sistema de:', 'SOCIOLOGIA', 'FACIL', 0),
(1642, 'O conceito formulado por Kimberlé Crenshaw para analisar a sobreposição simultânea de opressões de raça, gênero e classe social é a:', 'SOCIOLOGIA', 'MEDIO', 0),
(1643, 'O conceito sociológico que demonstra que a desigualdade racial não é apenas uma anomalia individual, mas permeia leis e instituições é o:', 'SOCIOLOGIA', 'FACIL', 0),
(1644, 'O modelo de produção fabril do início do século XX que introduziu a gerência científica com cronometragem minuciosa dos movimentos dos operários foi o:', 'SOCIOLOGIA', 'FACIL', 1),
(1645, 'O fenômeno recente do mundo do trabalho marcado pela informalidade, desregulamentação de direitos e subordinação a plataformas de aplicativos é a:', 'SOCIOLOGIA', 'FACIL', 0),
(1646, 'Segundo o sociólogo T. H. Marshall, os direitos de cidadania conquistados historicamente no século XX voltados à saúde, educação e previdência são os:', 'SOCIOLOGIA', 'MEDIO', 0),
(1647, 'A obra clássica de Gilberto Freyre publicada em 1933 que analisou a formação da sociedade colonial patriarcal a partir da miscigenação é:', 'SOCIOLOGIA', 'FACIL', 2),
(1648, 'A controversa tese sociológica brasileira que postulava a existência de uma suposta convivência harmoniosa sem conflitos raciais severos no país é o:', 'SOCIOLOGIA', 'FACIL', 1),
(1649, 'O historiador e sociólogo autor de ''Raízes do Brasil'' (1936) que formulou o célebre conceito do ''Homem Cordial'' foi:', 'SOCIOLOGIA', 'FACIL', 1),
(1650, 'Para Sérgio Buarque de Holanda, o conceito de ''Homem Cordial'' designa:', 'SOCIOLOGIA', 'MEDIO', 2),
(1651, 'O eminente sociólogo paulista da USP que desmistificou o mito da democracia racial em ''A Integração do Negro na Sociedade de Classes'' foi:', 'SOCIOLOGIA', 'FACIL', 2);

